async function blog(){let posts=[];try{posts=await fetch(API+'/posts').then(r=>r.json())}catch{}shell(`<main class="page"><div class="page-head"><span class="eyebrow">BLOG</span><h1>Ý tưởng để<br><em>trao điều ý nghĩa.</em></h1><p>Những gợi ý nhỏ về quà tặng, NFC, thiết kế và cách kể chuyện bằng ký ức.</p><div class="search"><span>⌕</span><input id="search" placeholder="Tìm bài viết..."></div></div><div id="posts" class="blog-grid">${posts.map((p,i)=>`<a class="blog-card" href="#/blog/${p.slug}"><div class="blog-cover c${i%4}"><span>${String(i+1).padStart(2,'0')}</span></div><small>${esc(p.category)} · 4 phút đọc</small><h2>${esc(p.title)}</h2><p>${esc(p.excerpt)}</p><span>Đọc bài →</span></a>`).join('')}</div></main>`); $('#search')?.addEventListener('input',e=>$$('#posts .blog-card').forEach(c=>c.style.display=c.innerText.toLowerCase().includes(e.target.value.toLowerCase())?'block':'none'))}
async function blogPost(slug){const p=await fetch(API+'/posts/'+encodeURIComponent(slug)).then(r=>r.json());if(p.message)return shell(`<main class="page"><h1>Không tìm thấy bài viết.</h1></main>`);shell(`<main class="page narrow post"><span class="eyebrow">${esc(p.category)} · 4 PHÚT</span><h1>${esc(p.title)}</h1><p class="lead">${esc(p.excerpt)}</p><div class="post-cover"><span>FRAMIE</span><strong>${esc(p.title)}</strong></div><div class="post-body">${esc(p.body).split(/\n+/).map(x=>`<p>${x}</p>`).join('')}</div><a class="text-link" href="#/blog">← Về Blog</a></main>`)}
function shop(){shell(`<main class="page"><div class="page-head"><span class="eyebrow">CỬA HÀNG · MADE FOR COUPLES</span><h1>Chọn một chiếc Framie<br><em>để khởi đầu hành trình.</em></h1><p>Với ba mức trải nghiệm linh hoạt, Framie giúp bạn biến một kỷ niệm của hai người thành món quà hữu hình và một không gian digital riêng.</p></div><div class="shop-grid">${plans.map((p,i)=>{const sw=[['#ffffff','/couple-1.jpg'],['#E8D4D2','/couple-2.jpg'],['#FFD3D6','/framie-standard-couple.jpg']][i];return `<article class="shop-card" data-plan-card="${p.code}"><div class="shop-art"><div class="shop-frame-showcase"><div class="frame-product-shell" style="--frame-color:${sw[0]}"><div class="fake-frame shop-frame-${i+1}"><img src="${sw[1]}" alt="${p.name} preview"><span>NFC</span></div></div></div></div><div class="shop-info"><div class="plan-top"><b>${p.number}</b>${p.popular?'<span>Được chọn nhiều</span>':''}</div><h2>${p.name}</h2><p>${p.description}</p><ul>${p.features.map(f=>`<li>✓ ${f}</li>`).join('')}</ul><p class="fit"><b>Phù hợp:</b> ${p.note}</p><div class="price-row"><strong>${money(p.price)}</strong><button class="btn primary shop-setup" data-plan="${p.code}">Thiết lập →</button></div></div></article>`}).join('')}</div><section class="product-details"><span class="eyebrow">THÔNG TIN SẢN PHẨM</span><h2>Đẹp ở ngoài. Riêng ở bên trong.</h2><div class="tabs"><button class="active" data-tab="material">Chất liệu</button><button data-tab="spec">Thông số</button><button data-tab="use">Hướng dẫn</button><button data-tab="warranty">Bảo hành</button></div><div id="tab-panel" class="tab-panel"><p>Khung được định hướng theo phong cách premium, bề mặt tối giản, tông màu ấm và ưu tiên cảm giác quà tặng. Nội dung NFC là lớp số đi kèm sản phẩm.</p></div></section></main>`);$$('.shop-setup').forEach(b=>b.onclick=()=>{S.productPlan=b.dataset.plan;S.design.plan=S.productPlan;persist();location.hash='/setup'});const data={material:'Khung có các lựa chọn Trắng kem, Gỗ sáng, Đen, Beige, Hồng pastel và Đỏ trầm.',spec:'Kích thước 10×15, 13×18, 15×21 và 20×30 cm; khung đứng hoặc ngang.',use:'Thiết kế → xem lại → đặt hàng. Khi nhận quà, đưa điện thoại hỗ trợ NFC tới vùng NFC trên khung để mở trang riêng.',warranty:'Chính sách đổi trả và bảo hành được cập nhật theo đơn hàng thực tế. Liên hệ Framie khi cần hỗ trợ.'};$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#tab-panel').innerHTML=`<p>${data[b.dataset.tab]}</p>`})}
function contact(){shell(`<main class="page contact"><div class="contact-copy"><span class="eyebrow">LIÊN HỆ</span><h1>Để Framie<br><em>nghe câu chuyện của bạn.</em></h1><p class="lead">Cần tư vấn thiết kế, đơn hàng hay hỗ trợ NFC? Hãy để lại thông tin, đội ngũ Framie sẽ phản hồi.</p><div class="contact-list"><div><b>Hotline</b><a href="tel:0364539533">0364539533</a></div><div><b>Email</b><a href="mailto:duandigitalmarketing@gmail.com">duandigitalmarketing@gmail.com</a></div><div><b>Địa chỉ</b><span>279 Nguyễn Tri Phương, Phường Diên Hồng, TP. Hồ Chí Minh<br>Plus Code: 7P28QM69+C9</span></div></div></div><div class="contact-side"><form id="contact" class="card-form"><h3>Gửi yêu cầu</h3><input name="name" required placeholder="Họ và tên"><input name="email" type="email" required placeholder="Email"><input name="phone" required placeholder="Số điện thoại"><textarea name="message" required placeholder="Nội dung bạn muốn Framie hỗ trợ"></textarea><button class="btn primary full">Gửi yêu cầu →</button><p id="contact-msg" class="form-note"></p></form><div class="map-card"><div class="map-top"><span>FRAMIE STUDIO</span><b>279 Nguyễn Tri Phương</b></div><iframe title="Framie map" loading="lazy" src="https://www.google.com/maps?q=279%20Nguy%E1%BB%85n%20Tri%20Ph%C6%B0%C6%A1ng%2C%20Ph%C6%B0%E1%BB%9Dng%20Di%C3%AAn%20H%E1%BB%93ng%2C%20TP.%20H%E1%BB%93%20Ch%C3%AD%20Minh%207P28QM69%2BC9&output=embed"></iframe></div></div></main>`);$('#contact').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch(API+'/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(f)});const x=await r.json();$('#contact-msg').textContent=x.message||'Đã gửi yêu cầu.';e.currentTarget.reset()}}
function policy(){shell(`<main class="page narrow policy"><span class="eyebrow">PHÁP LÝ</span><h1>Chính sách<br><em>Framie.</em></h1><div class="policy-body">${PRIVACY}<h2 id="refund">ĐỔI TRẢ & BẢO HÀNH</h2><p>FRAMIE tiếp nhận hỗ trợ đối với sản phẩm có lỗi sản xuất, sai khác so với cấu hình đã xác nhận hoặc các vấn đề phát sinh do hệ thống. Vui lòng liên hệ FRAMIE với mã đơn hàng và thông tin cần thiết để được hướng dẫn xử lý.</p></div></main>`)}
function auth(){const reg=location.hash==='#/register',forgot=location.hash==='#/forgot';if(forgot){shell(`<main class="auth-page"><div class="auth-card"><span class="eyebrow">KHÔI PHỤC TÀI KHOẢN</span><h1>Đặt lại mật khẩu.</h1><p>Nhập email để nhận hướng dẫn khôi phục.</p><form id="forgot"><input name="identity" type="email" required placeholder="Email"><button class="btn primary full">Gửi hướng dẫn →</button></form><a class="switch" href="#/login">← Quay lại đăng nhập</a></div></main>`);$('#forgot').onsubmit=async e=>{e.preventDefault();await fetch(API+'/auth/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});alert('Nếu tài khoản tồn tại, hướng dẫn khôi phục đã được tiếp nhận.');return} ;return}
shell(`<main class="auth-page"><div class="auth-side"><span class="eyebrow">FRAMIE ACCOUNT</span><h2>Một nơi để<br><em>giữ lại những gì bạn đã tạo.</em></h2><p>Lưu thiết kế, quản lý đơn hàng và chỉnh sửa nội dung NFC bất cứ lúc nào.</p></div><div class="auth-card"><span class="eyebrow">${reg?'ĐĂNG KÝ':'ĐĂNG NHẬP'}</span><h1>${reg?'Tạo tài khoản Framie.':'Chào mừng trở lại.'}</h1><form id="auth">${reg?`<input name="name" required placeholder="Họ và tên"><input name="phone" required placeholder="Số điện thoại">`:''}<input name="${reg?'email':'identity'}" ${reg?'type="email"':''} required placeholder="${reg?'Email':'Email hoặc số điện thoại'}"><input name="password" type="password" minlength="6" required placeholder="Mật khẩu"><div class="auth-options">${reg?'':`<label><input type="checkbox"> Ghi nhớ đăng nhập</label><a href="#/forgot">Quên mật khẩu?</a>`}</div><div id="err"></div><button class="btn primary full">${reg?'Tạo tài khoản':'Đăng nhập'} →</button></form><a href="${API}/auth/google/start" class="btn ghost full google">G <span>Tiếp tục với Google</span></a><a class="switch" href="#/${reg?'login':'register'}">${reg?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký'}</a></div></main>`);$('#auth').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));const endpoint=reg?'register':'login';const r=await fetch(API+'/auth/'+endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const x=await r.json();if(!r.ok){$('#err').innerHTML=`<div class="error">${esc(x.message)}</div>`;return}setAuth(x);location.hash='/dashboard'}}
const PRIVACY=`<h2>CHÍNH SÁCH BẢO MẬT THÔNG TIN - FRAMIE</h2><p>Chính sách này giải thích cách FRAMIE thu thập, sử dụng và bảo vệ dữ liệu khi bạn tạo, lưu trữ và hiển thị nội dung trên các sản phẩm quà tặng tích hợp NFC.</p><p>Bằng việc truy cập website, tạo nội dung hoặc chủ động tải dữ liệu lên hệ thống FRAMIE, bạn xác nhận đã đọc, hiểu và đồng ý với các điều khoản trong chính sách này.</p><h3>1. PHẠM VI VÀ CÁC LOẠI DỮ LIỆU THU THẬP</h3><ul><li><b>Dữ liệu nội dung:</b> hình ảnh, video, ghi âm âm thanh, văn bản/lời nhắn cá nhân.</li><li><b>Thông tin tài khoản:</b> họ tên, email hoặc số điện thoại khi đăng ký.</li><li><b>Thông tin đơn hàng:</b> dữ liệu cần thiết để thanh toán, giao hàng và hỗ trợ khách hàng.</li></ul><p>FRAMIE chỉ thu thập và xử lý những thông tin cần thiết cho việc cung cấp dịch vụ.</p><h3>2. PHƯƠNG THỨC TẢI DỮ LIỆU VÀ QUYỀN TRUY CẬP THIẾT BỊ</h3><ul><li>Tải hình ảnh, video, âm thanh và tệp liên quan trực tiếp từ máy tính hoặc điện thoại.</li><li>Khi ghi âm hoặc quay video trực tiếp, trình duyệt sẽ yêu cầu quyền Microphone/Camera.</li><li>Người dùng có thể cấp quyền truy cập thư viện ảnh hoặc tệp tin để lựa chọn nội dung.</li></ul><p>Bạn có quyền từ chối hoặc hủy các quyền này trong phần cài đặt của thiết bị/trình duyệt. Việc từ chối có thể khiến một số tính năng không hoạt động.</p><h3>3. MỤC ĐÍCH XỬ LÝ VÀ SỬ DỤNG DỮ LIỆU</h3><ul><li>Lưu trữ và hiển thị ảnh, video, âm thanh, văn bản.</li><li>Liên kết sản phẩm vật lý với trải nghiệm số thông qua mã định danh NFC.</li><li>Truy xuất nội dung khi người nhận chạm NFC hoặc truy cập đường dẫn được liên kết.</li><li>Xử lý, xác nhận và giao đơn hàng.</li><li>Cải thiện hiệu suất, phát hiện lỗi và nâng cao trải nghiệm.</li></ul><h3>4. CAM KẾT BẢO MẬT VÀ BẢO VỆ DỮ LIỆU</h3><ul><li>Không bán hoặc cho thuê ảnh, video, âm thanh và lời nhắn cá nhân cho bên thứ ba nhằm mục đích quảng cáo/tiếp thị.</li><li>FRAMIE không tự động sử dụng nội dung cá nhân cho hoạt động truyền thông hoặc đăng tải công khai.</li><li>Người tạo có thể bật <b>mật khẩu bảo vệ NFC</b>; khi bật, người nhận phải nhập đúng mật khẩu mới xem được nội dung.</li><li>Nội dung NFC có thể được quản trị và thay đổi từ Dashboard của chủ thiết kế.</li></ul><h3>5. QUYỀN KIỂM SOÁT VÀ XÓA DỮ LIỆU</h3><p>Theo quy định pháp luật hiện hành, bao gồm Nghị định 13/2023/NĐ-CP, người dùng có quyền biết, đồng ý, truy cập, chỉnh sửa, xóa, phản đối hoặc yêu cầu hạn chế xử lý dữ liệu trong phạm vi hệ thống hỗ trợ.</p><p>Lưu ý: xóa dữ liệu hoặc rút lại sự đồng ý có thể khiến nội dung NFC tương ứng không còn hiển thị.</p><h3>6. CHIA SẺ DỮ LIỆU VỚI BÊN THỨ BA</h3><ul><li>Nhà cung cấp hạ tầng lưu trữ đám mây.</li><li>Đối tác giao nhận/vận chuyển.</li><li>Đơn vị trung gian thanh toán.</li></ul><p>FRAMIE chỉ cung cấp thông tin cần thiết để các bên thực hiện chức năng được giao và không bán dữ liệu cá nhân cho mục đích thương mại.</p><h3>7. BẢO MẬT SẢN PHẨM NFC</h3><p>Chip NFC chỉ chứa đường dẫn liên kết (URL), không lưu trực tiếp hình ảnh, video hoặc dữ liệu cá nhân. Khi mất sản phẩm hoặc nghi ngờ truy cập trái phép, hãy liên hệ FRAMIE để được hỗ trợ khóa nội dung hoặc đặt lại mã bảo mật.</p><h3>8. THỜI GIAN LƯU TRỮ DỮ LIỆU</h3><p>FRAMIE lưu trữ nội dung trong khoảng thời gian cần thiết để cung cấp dịch vụ hoặc theo thời hạn của gói dịch vụ. Một số dữ liệu có thể được lưu lâu hơn nếu cần để thực hiện nghĩa vụ pháp lý hoặc giải quyết tranh chấp.</p><h3>9. THAY ĐỔI CHÍNH SÁCH</h3><p>FRAMIE có thể cập nhật Chính sách này để phản ánh thay đổi của sản phẩm, công nghệ hoặc pháp luật. Phiên bản cập nhật sẽ được đăng tải công khai trên website kèm thời điểm hiệu lực.</p><h3>10. THÔNG TIN LIÊN HỆ</h3><p>Đơn vị: FRAMIE<br>Địa chỉ: 279 Nguyễn Tri Phương, Phường Diên Hồng, TP. Hồ Chí Minh<br>Hotline hỗ trợ: 0364539533<br>Email tiếp nhận: duandigitalmarketing@gmail.com<br>Website chính thức: FRAMIE</p><p><b>Chính sách này có hiệu lực kể từ ngày đăng tải.</b></p>`
function privacy(){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card privacy"><button class="close" aria-label="Đóng">×</button><div class="privacy-scroll">${PRIVACY}</div><div class="privacy-consents"><label class="check"><input id="privacy-ok" type="checkbox"> Tôi đã đọc, hiểu và đồng ý với Điều khoản sử dụng cùng Chính sách bảo mật của FRAMIE.</label><label class="check"><input id="rights-ok" type="checkbox"> Tôi xác nhận có đầy đủ quyền sở hữu/quyền sử dụng đối với hình ảnh, video, âm thanh và văn bản tải lên; nội dung không vi phạm bản quyền, pháp luật hoặc quyền riêng tư của người khác.</label></div><button id="privacy-agree" class="btn primary full" disabled>Đồng ý & tiếp tục →</button></div>`;document.body.appendChild(m);$('.close',m).onclick=()=>m.remove();const sync=()=>$('#privacy-agree',m).disabled=!($('#privacy-ok',m).checked&&$('#rights-ok',m).checked);$('#privacy-ok',m).onchange=sync;$('#rights-ok',m).onchange=sync;$('#privacy-agree',m).onclick=()=>{S.privacy=true;S.step=4;persist();m.remove();renderSetup()}}
function resetDesign(){S.design=defaultDesign();S.nfc=defaultNfc();S.selected=null;S.nfcSelected=null;S.step=1;persist()}
function renderSetup(){
  const titles={1:'Chọn gói',2:'Chọn khung',4:'Custom khung vật lý',5:'Custom nội dung NFC',6:'Bảo mật',7:'Preview & đặt hàng'};
  const labels=[[1,'Chọn gói'],[2,'Chọn khung'],[4,'Thiết kế vật lý'],[5,'Nội dung NFC'],[6,'Bảo mật'],[7,'Xem lại']];
  if(S.step===3){S.step=2;persist();privacy();return}
  const current=labels.findIndex(x=>x[0]===S.step);
  const stepNo=current>=0?`${current+1}/${labels.length}`:'1/6';
  shell(`<main class="setup"><aside class="setup-side"><a href="#/">← Trang chủ</a><div class="setup-title"><span class="eyebrow">TRẠM THIẾT LẬP</span><h2>Biến ý tưởng<br><em>thành Framie.</em></h2><p class="setup-couple-note">Thiết kế riêng cho câu chuyện của hai người.</p></div><div class="progress">${labels.map(([step,label],i)=>`<button type="button" data-step="${step}" class="${S.step===step?'active':''}"><b>0${i+1}</b><span>${label}</span></button>`).join('')}</div></aside><section class="setup-main"><div class="setup-head"><div><span class="eyebrow">BƯỚC ${stepNo}</span><h1>${titles[S.step]||'Framie'}</h1></div><div class="setup-head-actions"><button id="reset-design" class="icon-btn" title="Làm mới" aria-label="Làm mới">↻</button><a href="#/dashboard" class="icon-btn" aria-label="Dashboard"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="6" height="6" rx="1"></rect><rect x="14" y="4" width="6" height="6" rx="1"></rect><rect x="4" y="14" width="6" height="6" rx="1"></rect><rect x="14" y="14" width="6" height="6" rx="1"></rect></svg></a><button id="draft" class="btn ghost">Lưu bản nháp</button></div></div><div class="setup-body" id="setup-body"></div><div class="setup-foot"><button id="prev" class="btn ghost" ${S.step===1?'disabled':''}>← Quay lại</button><button id="next" class="btn primary">${S.step===7?'Đặt hàng thiết kế này':'Tiếp tục'} →</button></div></section></main>`);
  $$('[data-step]').forEach(b=>b.onclick=()=>{const n=+b.dataset.step;if(n>=4&&!S.privacy){privacy();return}S.step=n;persist();renderSetup()});
  $('#prev').onclick=()=>{if(S.step===4)S.step=2;else if(S.step===5)S.step=4;else if(S.step===6)S.step=5;else if(S.step===7)S.step=6;else if(S.step>1)S.step--;persist();renderSetup()};
  $('#next').onclick=async()=>{if(S.step===2){privacy();return}if(S.step===7){const d=await saveDesign('ready');if(d)location.hash='/checkout?design='+d.id;return}S.step++;persist();renderSetup()};
  $('#draft').onclick=()=>saveDesign('draft',true);$('#reset-design').onclick=()=>{if(confirm('Làm mới toàn bộ thiết kế hiện tại?')){resetDesign();renderSetup()}};
  if(S.step===1)planStep();else if(S.step===2)frameStep();else if(S.step===4)physicalStep();else if(S.step===5)nfcStep();else if(S.step===6)securityStep();else reviewStep();
}
function securityStep(){
  const enabled=!!S.nfc.passwordEnabled;
  $('#setup-body').innerHTML=`<div class="security-step-shell"><div class="security-step-card"><span class="security-lock">🔒</span><span class="eyebrow">BẢO MẬT NFC</span><h2>Bạn có muốn đặt mật khẩu cho trang kỷ niệm?</h2><p>Mật khẩu sẽ được gắn với NFC này. Người nhận chỉ xem được nội dung sau khi nhập đúng mật khẩu.</p><div class="security-choice"><button type="button" class="security-choice-btn ${enabled?'selected':''}" id="security-yes"><b>Có, đặt mật khẩu</b><span>Trang NFC sẽ được bảo vệ.</span></button><button type="button" class="security-choice-btn ${!enabled?'selected':''}" id="security-no"><b>Không cần mật khẩu</b><span>Mở nội dung trực tiếp.</span></button></div><div id="security-password-wrap" class="security-password-wrap" ${enabled?'':'hidden'}><label>Mật khẩu NFC<input id="security-password" type="password" minlength="4" autocomplete="new-password" value="${esc(S.nfc.password||'')}" placeholder="Nhập tối thiểu 4 ký tự"><small>Chỉ bạn mới có thể thay đổi mật khẩu này trong Dashboard.</small></label></div><div class="security-step-actions"><span class="security-state">${enabled?'🔒 Đang bật bảo vệ':'🔓 Không đặt mật khẩu'}</span><button id="security-continue" class="btn primary">Tiếp tục →</button></div></div></div>`;
  const yes=$('#security-yes'),no=$('#security-no'),wrap=$('#security-password-wrap'),input=$('#security-password'),state=$('.security-state');
  const setEnabled=v=>{S.nfc.passwordEnabled=v;if(!v){delete S.nfc.password;S.nfc.passwordHash='';}wrap.hidden=!v;yes.classList.toggle('selected',v);no.classList.toggle('selected',!v);state.textContent=v?'🔒 Đang bật bảo vệ':'🔓 Không đặt mật khẩu';persist()};
  yes.onclick=()=>setEnabled(true);no.onclick=()=>setEnabled(false);input?.addEventListener('input',e=>{S.nfc.password=e.target.value;persist()});
  $('#security-continue').onclick=()=>{if(S.nfc.passwordEnabled&&String(S.nfc.password||'').length<4){alert('Mật khẩu NFC tối thiểu 4 ký tự.');input?.focus();return}S.step=7;persist();renderSetup()};
}
function planStep(){const cards=plans.map(p=>`<button type="button" class="selection ${S.design.plan===p.code?'selected':''}" data-plan="${p.code}"><div class="plan-top"><b>${p.number}</b>${p.popular?'<span>Được chọn nhiều</span>':''}</div><h2>${p.name}</h2><p>${p.description}</p><strong>${money(p.price)}</strong><ul>${p.features.map(f=>`<li>✓ ${f}</li>`).join('')}</ul><small>${p.note}</small></button>`).join('');$('#setup-body').innerHTML=`<div class="selection-grid">${cards}</div>`;$$('[data-plan]').forEach(b=>b.onclick=()=>{S.design.plan=b.dataset.plan;S.productPlan=b.dataset.plan;persist();planStep()})}
function frameStep(){$('#setup-body').innerHTML=`<div class="frame-grid"><div class="frame-controls"><div class="control-group"><h3>Frame orientation</h3><div class="choices">${['portrait','landscape'].map(x=>`<button type="button" class="choice ${S.design.frame===x?'selected':''}" data-frame="${x}"><div class="choice-frame ${x}"></div><span>${x==='portrait'?'Khung đứng':'Khung ngang'}</span></button>`).join('')}</div></div><div class="control-group"><h3>Frame colors</h3><div class="swatches">${colors.map(c=>`<button type="button" class="swatch ${S.design.color===c[0]?'selected':''}" data-color="${c[0]}" title="${c[1]}" style="--sw:${c[2]}"></button>`).join('')}</div></div><div class="control-group"><h3>Frame sizes</h3><div class="sizes">${sizes.map(x=>`<button type="button" class="size ${S.design.size===x?'selected':''}" data-size="${x}">${x}</button>`).join('')}</div></div></div><div>${framePreview()}<div class="frame-summary"><span>${S.design.frame==='portrait'?'Khung đứng':'Khung ngang'}</span><span>${S.design.size}</span></div></div></div>`;$$('[data-frame]').forEach(b=>b.onclick=()=>{S.design.frame=b.dataset.frame;persist();frameStep()});$$('[data-color]').forEach(b=>b.onclick=()=>{S.design.color=b.dataset.color;persist();frameStep()});$$('[data-size]').forEach(b=>b.onclick=()=>{S.design.size=b.dataset.size;persist();frameStep()})}
function framePreview(scale='normal'){return `<div class="preview-wrap ${scale}"><span>LIVE PREVIEW</span><div id="physical-canvas" class="frame-preview ${S.design.frame} ${S.design.color}">${[...S.design.elements].sort((a,b)=>(a.z||0)-(b.z||0)).map(e=>renderPhysical(e,false)).join('')}<span class="nfc-badge">NFC</span></div><small>${S.design.frame==='portrait'?'Đứng':'Ngang'} · ${S.design.size}</small></div>`}
function renderPhysical(el,interactive=true){const selected=interactive&&S.selected===el.id?'selected':'';const heightStyle=el.type==='image'?`${el.height??100}%`:`${el.height||70}px`;const s=`left:${el.x}%;top:${el.y}%;width:${el.width||35}%;height:${heightStyle};z-index:${el.z||1};transform:translate(-50%,-50%) rotate(${el.rotate||0}deg)`;if(el.type==='image')return `<div class="physical image ${selected}" data-el="${el.id}" style="${s}"><img src="${esc(el.src)}" style="object-position:${el.cropX??50}% ${el.cropY??50}%;transform:scale(${el.zoom||1})"></div>`;if(el.type==='sticker')return `<div class="physical sticker ${selected}" data-el="${el.id}" style="${s};font-size:${el.size||40}px">${esc(el.text)}</div>`;return `<div class="physical text ${selected}" data-el="${el.id}" style="${s};font-size:${el.size||18}px;font-family:${el.font||'Playfair Display'}">${esc(el.text).replace(/\n/g,'<br>')}</div>`}
function physicalStep(){
  $('#setup-body').innerHTML=`<div class="editor-layout"><div class="editor-tools"><label class="tool">＋<b>Ảnh</b><input id="upload-physical" type="file" accept="image/*"></label><button class="tool" id="add-text" type="button">T<b>Văn bản</b></button><button class="tool" id="stickers" type="button">✦<b>Sticker</b></button></div><div class="editor-area">${framePreview()}</div><aside class="inspector">${S.selected?physicalInspector():`<div class="empty"><div>✦</div><h3>Chọn một thành phần</h3><p>Thêm ảnh, chữ hoặc sticker để bắt đầu. Click để chọn, kéo để di chuyển.</p></div>`}</aside></div>`;
  $('#upload-physical').onchange=e=>addImage(e,'physical');
  $('#add-text').onclick=()=>{const id='e'+Date.now();const maxZ=Math.max(0,...S.design.elements.map(x=>x.z||0));S.design.elements.push({id,type:'text',x:50,y:50,size:23,width:60,height:70,rotate:0,z:maxZ+1,text:'Nhập nội dung',font:'Playfair Display'});S.selected=id;persist();physicalStep()};
  $('#stickers').onclick=()=>stickerModal(false);bindPhysicalDrag();wirePhysicalInspector();
}
function renderPhysicalInspectorOnly(){const panel=$('.editor-layout .inspector');if(!panel)return;panel.innerHTML=S.selected?physicalInspector():`<div class="empty"><div>✦</div><h3>Chọn một thành phần</h3><p>Thêm ảnh, chữ hoặc sticker để bắt đầu. Click để chọn, kéo để di chuyển.</p></div>`;$$('.physical').forEach(n=>n.classList.toggle('selected',n.dataset.el===S.selected));wirePhysicalInspector()}
function selectPhysical(id){S.selected=id;persist();renderPhysicalInspectorOnly()}
async function addImage(e,kind){const f=e.target.files?.[0];if(!f)return;if(!S.user)return;const data=await fileToDataURL(f);const url=await uploadData(data,f.type);const id=(kind==='physical'?'e':'n')+Date.now();if(kind==='physical'){const isFirst=!S.design.elements.some(x=>x.type==='image');const maxZ=Math.max(0,...S.design.elements.map(x=>x.z||0));S.design.elements.unshift({id,type:'image',src:url,x:50,y:50,width:isFirst?100:55,height:isFirst?100:65,rotate:0,z:isFirst?0:maxZ+1,zoom:1,cropX:50,cropY:50});S.selected=id;persist();physicalStep()}e.target.value=''}
function fileToDataURL(f){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}
async function uploadData(data,mime){const r=await fetch(API+'/upload',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+S.token},body:JSON.stringify({data,mime})});const x=await r.json();if(!r.ok)throw new Error(x.message||'Upload thất bại');return x.url}
function physicalInspector(){const el=S.design.elements.find(x=>x.id===S.selected);if(!el)return '';const isMedia=el.type==='image';return `<div class="inspector-head"><div><span>CANVA STYLE EDITOR</span><b>${el.type==='image'?'Ảnh':el.type==='sticker'?'Sticker':'Văn bản'}</b></div><button id="delete-physical" type="button">Xoá</button></div>${el.type==='text'?`<label>Nội dung<textarea id="physical-text">${esc(el.text)}</textarea></label><label>Font<select id="font"><option ${el.font==='Playfair Display'?'selected':''}>Playfair Display</option><option ${el.font==='Cormorant Garamond'?'selected':''}>Cormorant Garamond</option><option ${el.font==='DM Sans'?'selected':''}>DM Sans</option><option ${el.font==='Georgia'?'selected':''}>Georgia</option><option ${el.font==='Arial'?'selected':''}>Arial</option></select></label>`:''}${isMedia?`<label class="upload-box">Thay ảnh<input id="replace-physical" type="file" accept="image/*"></label><div class="control"><span>Zoom / scale</span><input id="p-zoom" type="range" min=".5" max="5" step=".05" value="${el.zoom||1}"></div><div class="control"><span>Crop X</span><input id="p-cropx" type="range" min="0" max="100" value="${el.cropX??50}"></div><div class="control"><span>Crop Y</span><input id="p-cropy" type="range" min="0" max="100" value="${el.cropY??50}"></div>`:''}<div class="control"><span>Kích thước</span><input id="p-size" type="range" min="8" max="90" value="${el.size||18}"></div><div class="control"><span>Độ rộng</span><input id="p-width" type="range" min="5" max="100" value="${el.width||35}"></div><div class="control"><span>Chiều cao</span><input id="p-height" type="range" min="30" max="600" value="${el.height||70}"></div><div class="grid2"><label>X<input id="p-x" type="number" min="0" max="100" value="${Math.round(el.x)}"></label><label>Y<input id="p-y" type="number" min="0" max="100" value="${Math.round(el.y)}"></label></div><div class="control"><span>Góc xoay</span><input id="p-rotate" type="range" min="-180" max="180" value="${el.rotate||0}"></div><div class="quick-actions"><button type="button" id="p-center">↔ Căn giữa</button><button type="button" id="p-front">Đưa lên cùng</button></div><div class="layer-actions"><button id="layer-up" type="button">↑ Lên lớp</button><button id="layer-down" type="button">↓ Xuống lớp</button></div>`}
function updatePhysicalNode(el){const node=$(`.physical[data-el="${el.id}"]`);if(!node)return;node.style.left=el.x+'%';node.style.top=el.y+'%';node.style.width=(el.width||35)+'%';node.style.height=el.type==='image'?((el.height??100)+'%'):((el.height||70)+'px');node.style.fontSize=(el.size||18)+'px';node.style.transform=`translate(-50%,-50%) rotate(${el.rotate||0}deg)`;node.style.zIndex=el.z||1;const img=node.querySelector('img');if(img){img.style.objectPosition=`${el.cropX??50}% ${el.cropY??50}%`;img.style.transform=`scale(${el.zoom||1})`;}if(el.type==='text'){node.innerHTML=esc(el.text).replace(/\n/g,'<br>');node.style.fontFamily=el.font||'Playfair Display';}}
function bindPhysicalDrag(){$$('.physical').forEach(node=>{node.onpointerdown=e=>{const id=node.dataset.el;const target=S.design.elements.find(x=>x.id===id);if(!target)return;selectPhysical(id);const isControl=e.target.closest('button,audio,video,iframe,input,textarea,select');const isHandle=e.target.closest('.drag-handle');if(isControl&&!isHandle)return;e.preventDefault();e.stopPropagation();const rect=node.parentElement.getBoundingClientRect(),sx=e.clientX,sy=e.clientY,ox=target.x,oy=target.y;node.setPointerCapture?.(e.pointerId);const move=ev=>{target.x=Math.max(2,Math.min(98,ox+(ev.clientX-sx)/rect.width*100));target.y=Math.max(2,Math.min(98,oy+(ev.clientY-sy)/rect.height*100));updatePhysicalNode(target)};const up=()=>{window.removeEventListener('pointermove',move);persist()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})};node.onclick=()=>selectPhysical(node.dataset.el)})}
function swapLayer(list,id,dir){const sorted=[...list].sort((a,b)=>(a.z||0)-(b.z||0));const i=sorted.findIndex(x=>x.id===id);const j=dir>0?i+1:i-1;if(i<0||j<0||j>=sorted.length)return;[sorted[i].z,sorted[j].z]=[(sorted[j].z||0),(sorted[i].z||0)];}
function wirePhysicalInspector(){const el=S.design.elements.find(x=>x.id===S.selected);if(!el)return;const on=(id,k,fn=v=>v)=>$(id)?.addEventListener('input',e=>{el[k]=fn(e.target.value);persist();updatePhysicalNode(el)});on('#physical-text','text');on('#font','font');on('#p-zoom','zoom',Number);on('#p-cropx','cropX',Number);on('#p-cropy','cropY',Number);on('#p-height','height',Number);on('#p-size','size',Number);on('#p-width','width',Number);on('#p-x','x',Number);on('#p-y','y',Number);on('#p-rotate','rotate',Number);$('#delete-physical')?.addEventListener('click',()=>{S.design.elements=S.design.elements.filter(x=>x.id!==S.selected);S.selected=null;persist();physicalStep()});$('#replace-physical')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{el.src=await uploadData(await fileToDataURL(f),f.type);persist();physicalStep()}catch(err){alert(err.message)}});$('#layer-up')?.addEventListener('click',()=>{swapLayer(S.design.elements,S.selected,1);persist();physicalStep()});$('#layer-down')?.addEventListener('click',()=>{swapLayer(S.design.elements,S.selected,-1);persist();physicalStep()});$('#p-center')?.addEventListener('click',()=>{el.x=50;el.y=50;persist();physicalStep()});$('#p-front')?.addEventListener('click',()=>{const m=Math.max(0,...S.design.elements.map(x=>x.z||0));el.z=m+1;persist();physicalStep()})}
function stickerModal(nfcMode){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card stickers"><div class="modal-head"><div><span class="eyebrow">STICKER</span><h2>Chọn một nét nhỏ.</h2></div><button class="close">×</button></div><div class="sticker-grid">${stickers.map(s=>`<button data-st="${encodeURIComponent(s[0])}"><span>${s[0]}</span><small>${s[1]}</small></button>`).join('')}</div></div>`;document.body.appendChild(m);$('.close',m).onclick=()=>m.remove();$$('[data-st]',m).forEach(b=>b.onclick=()=>{const val=decodeURIComponent(b.dataset.st);const id=(nfcMode?'n':'e')+Date.now();if(nfcMode){S.nfc.elements.push({id,type:'sticker',x:50,y:65,size:40,width:30,rotate:0,z:Math.max(0,...S.nfc.elements.map(x=>x.z||0))+1,text:val}) ;S.nfcSelected=id}else{S.design.elements.push({id,type:'sticker',x:50,y:50,size:42,width:30,rotate:0,z:Math.max(0,...S.design.elements.map(x=>x.z||0))+1,text:val});S.selected=id}m.remove();persist();nfcMode?nfcStep():physicalStep()})}
function bindAudioTriggers(root=document){$$('.audio-trigger',root).forEach(btn=>btn.onclick=()=>{const src=btn.dataset.audioSrc;if(!src)return;const existing=$('.inline-audio-player',btn.parentElement);if(existing){existing.play();return}const audio=document.createElement('audio');audio.className='inline-audio-player';audio.controls=true;audio.src=src;audio.autoplay=true;btn.insertAdjacentElement('afterend',audio);});$$('audio',root).forEach(a=>a.addEventListener('click',e=>e.stopPropagation()));}
function nfcStep(){$('#setup-body').innerHTML=`<div class="nfc-layout"><div class="nfc-tools"><button class="tool" id="nt" type="button">T<b>Văn bản</b></button><label class="tool">＋<b>Hình ảnh</b><input id="ni" type="file" accept="image/*"></label><button class="tool" id="na" type="button">◉<b>Âm thanh</b></button><button class="tool" id="ns" type="button">✦<b>Sticker</b></button><label class="tool">▣<b>Video</b><input id="nv" type="file" accept="video/*"></label><button class="tool" id="add-spotify" type="button">♫<b>Spotify</b></button></div><div class="phone-center"><div class="device-stage"><div class="device-phone" id="nfc-phone"><div class="dynamic-island"></div><div class="device-screen">${nfcPhoneContent()}</div></div></div></div><aside class="inspector nfc-inspector">${S.nfcSelected?nfcInspector():`<div class="empty"><div>⌁</div><h3>Nội dung NFC</h3><p>Click để chọn. Kéo để di chuyển. Mỗi lớp có thể đổi kích thước, chiều cao, xoay và sắp lớp.</p></div>`}</aside></div>`;$('#nt').onclick=()=>{const id='n'+Date.now();S.nfc.elements.push({id,type:'text',x:50,y:62,size:18,width:84,height:70,rotate:0,z:Math.max(0,...S.nfc.elements.map(x=>x.z||0))+1,text:'Nhập nội dung',font:'Playfair Display'});S.nfcSelected=id;persist();nfcStep()};$('#ni').onchange=e=>addNfcFile(e,'image');$('#nv').onchange=e=>addNfcFile(e,'video');$('#ns').onclick=()=>stickerModal(true);$('#na').onclick=()=>addNfcAudioElement();$('#add-spotify').onclick=()=>addSpotifyElement();bindNfcDrag();wireNfcInspector();bindAudioTriggers();bindSpotifyEmbeds()}
function renderNfcInspectorOnly(){const panel=$('.nfc-layout .nfc-inspector');if(!panel)return;panel.innerHTML=S.nfcSelected?nfcInspector():`<div class="empty"><div>⌁</div><h3>Nội dung NFC</h3><p>Click để chọn. Kéo để di chuyển. Mỗi lớp có thể đổi kích thước, chiều cao, xoay và sắp lớp.</p></div>`;$$('.nfc-el').forEach(n=>n.classList.toggle('selected',n.dataset.nfc===S.nfcSelected));wireNfcInspector();bindAudioTriggers(panel);bindSpotifyEmbeds(panel)}
function selectNfc(id){S.nfcSelected=id;persist();renderNfcInspectorOnly()}
function nfcPhoneContent(){return nfcPhoneContentFrom(S.nfc)}
function nfcPhoneContentFrom(x){const hasImage=(x.elements||[]).some(e=>e.type==='image');return `<div class="nfc-top">${logo('compact')}<span>tap to remember</span></div>${hasImage?'':`<div class="nfc-cover-placeholder"></div>`}${(x.elements||[]).slice().sort((a,b)=>(a.z||0)-(b.z||0)).map(e=>renderNfc(e,false)).join('')}${x.recording?`<div class="saved-audio"><button type="button" class="audio-trigger" data-audio-src="${esc(x.recording)}"><b>Lời nhắn thoại</b><span>Chạm để nghe</span></button><audio class="saved-audio-player" controls preload="metadata" src="${esc(x.recording)}"></audio></div>`:''}<div class="scroll-space"></div>`}
function nfcLandingContentFrom(x){const hasImage=(x.elements||[]).some(e=>e.type==='image');return `<div class="nfc-web-canvas">${hasImage?'':`<div class="nfc-cover-placeholder"></div>`}${(x.elements||[]).slice().sort((a,b)=>(a.z||0)-(b.z||0)).map(e=>renderNfc(e,false,'web')).join('')}${x.recording?`<div class="web-legacy-audio"><button type="button" class="audio-trigger" data-audio-src="${esc(x.recording)}"><b>Lời nhắn thoại</b><span>Chạm để nghe</span></button><audio controls preload="metadata" src="${esc(x.recording)}"></audio></div>`:''}</div>`}
function spotifyEmbedUrl(value){const v=String(value||'').trim();if(!v)return '';if(v.startsWith('spotify:')){const m=v.match(/^spotify:(track|album|playlist|episode|show|artist):([A-Za-z0-9]+)$/i);return m?`https://open.spotify.com/embed/${m[1]}/${m[2]}`:''}const m=v.match(/open\.spotify\.com\/(track|album|playlist|episode|show|artist)\/([A-Za-z0-9]+)/i);return m?`https://open.spotify.com/embed/${m[1]}/${m[2]}`:''}
function renderNfc(el,interactive=true,mode='phone'){const selected=interactive&&S.nfcSelected===el.id?'selected':'';const effectiveWidth=el.width||84;const h=el.height||(el.type==='spotify'?152:el.type==='audio'?74:el.type==='video'?210:el.type==='image'?220:70);const dragHandle=(el.type==='audio'||el.type==='spotify')?`<span class="drag-handle" title="Kéo để di chuyển">⠿</span>`:'';const heightStyle=mode==='web'?`${(h/730)*100}%`:`${h}px`;const s=`left:${el.x}%;top:${el.y}%;width:${effectiveWidth}%;height:${el.type==='text'?heightStyle:heightStyle};z-index:${el.z||1};font-size:${el.size||16}px;transform:translate(-50%,-50%) rotate(${el.rotate||0}deg)`;let inner;if(el.type==='image')inner=`<img src="${esc(el.src)}" style="object-position:${el.cropX??50}% ${el.cropY??50}%;transform:scale(${el.zoom||1})">`;else if(el.type==='video')inner=`<video controls playsinline preload="metadata" src="${esc(el.src)}"></video>`;else if(el.type==='audio')inner=el.src?`${dragHandle}<button type="button" class="nfc-audio audio-trigger" data-audio-src="${esc(el.src)}">◉ ${esc(el.label||el.text||'Lời nhắn thoại')} <span>· chạm để nghe</span></button>`:`${dragHandle}<div class="nfc-audio">◉ ${esc(el.label||el.text||'Lời nhắn thoại')} <span>· chưa có audio</span></div>`;else if(el.type==='spotify'){const embed=spotifyEmbedUrl(el.url);inner=embed?`${dragHandle}<div class="spotify-embed"><iframe src="${embed}" title="Spotify music" loading="lazy" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture"></iframe></div>`:`${dragHandle}<div class="nfc-audio">♫ Thêm link Spotify</div>`}else if(el.type==='sticker')inner=esc(el.text);else inner=`<span style="font-family:${esc(el.font||'Playfair Display')}">${esc(el.text).replace(/\n/g,'<br>')}</span>`;return `<div class="nfc-el ${el.type} ${selected}" data-nfc="${el.id}" style="${s}">${inner}</div>`}
function addSpotifyElement(){const url=prompt('Dán link Spotify (track / album / playlist / podcast):',S.nfc.spotify||'');if(url===null)return;const embed=spotifyEmbedUrl(url);if(!embed){alert('Link Spotify chưa đúng định dạng. Hãy dùng link từ open.spotify.com hoặc spotify:track/...');return}const id='n'+Date.now();S.nfc.elements.push({id,type:'spotify',x:50,y:80,width:94,height:168,size:12,rotate:0,z:Math.max(0,...S.nfc.elements.map(x=>x.z||0))+1,url});S.nfc.spotify=url;S.nfcSelected=id;persist();nfcStep()}
function addNfcAudioElement(){const id='n'+Date.now();S.nfc.elements.push({id,type:'audio',x:50,y:78,size:13,width:94,height:74,rotate:0,z:Math.max(0,...S.nfc.elements.map(x=>x.z||0))+1,text:'Lời nhắn thoại',label:'Lời nhắn thoại',src:null});S.nfcSelected=id;persist();nfcStep()}
async function addNfcFile(e,type){const f=e.target.files?.[0];if(!f)return;try{const src=await uploadData(await fileToDataURL(f),f.type);const id='n'+Date.now();S.nfc.elements.push({id,type,src,x:50,y:type==='image'?38:72,width:84,height:type==='image'?220:210,size:16,zoom:1,cropX:50,cropY:50,rotate:0,z:Math.max(0,...S.nfc.elements.map(x=>x.z||0))+1,text:''});S.nfcSelected=id;persist();nfcStep()}catch(err){alert(err.message)}e.target.value=''}
function startRecord(target=null){if(S.recording){S.mediaRecorder.stop();return}if(!navigator.mediaDevices?.getUserMedia){alert('Trình duyệt không hỗ trợ ghi âm. Hãy dùng Chrome/Safari mới.');return}navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{S.mediaStream=stream;S.recChunks=[];S.mediaRecorder=new MediaRecorder(stream);S.recording=true;S.mediaRecorder.ondataavailable=e=>e.data.size&&S.recChunks.push(e.data);S.mediaRecorder.onstop=async()=>{const blob=new Blob(S.recChunks,{type:'audio/webm'});const data=await fileToDataURL(blob);try{const src=await uploadData(data,'audio/webm');if(target){const el=S.nfc.elements.find(x=>x.id===target);if(el)el.src=src}else S.nfc.recording=src;persist();S.recording=false;nfcStep()}catch(err){alert(err.message);S.recording=false}stream.getTracks().forEach(t=>t.stop())};S.mediaRecorder.start();nfcStep()}).catch(()=>alert('Hãy cấp quyền Microphone cho trình duyệt để ghi âm.'))}
function updateNfcNode(el){const node=$(`.nfc-el[data-nfc="${el.id}"]`);if(!node)return;node.style.left=el.x+'%';node.style.top=el.y+'%';node.style.width=(el.width||84)+'%';node.style.height=(el.height||(el.type==='spotify'?152:el.type==='audio'?74:el.type==='video'?210:el.type==='image'?220:70))+'px';node.style.fontSize=(el.size||16)+'px';node.style.transform=`translate(-50%,-50%) rotate(${el.rotate||0}deg)`;node.style.zIndex=el.z||1;const img=node.querySelector('img');if(img){img.style.objectPosition=`${el.cropX??50}% ${el.cropY??50}%`;img.style.transform=`scale(${el.zoom||1})`;}const iframe=node.querySelector('iframe');if(iframe&&el.url){const src=spotifyEmbedUrl(el.url);if(src&&iframe.src!==src)iframe.src=src;}}
function bindNfcDrag(){$$('.nfc-el').forEach(el=>{el.onpointerdown=e=>{const id=el.dataset.nfc;const target=S.nfc.elements.find(x=>x.id===id);if(!target)return;selectNfc(id);const isControl=e.target.closest('button,audio,video,iframe,input,textarea,select');const isHandle=e.target.closest('.drag-handle');if(isControl&&!isHandle)return;e.preventDefault();e.stopPropagation();const rect=$('#nfc-phone .device-screen').getBoundingClientRect(),sx=e.clientX,sy=e.clientY,ox=target.x,oy=target.y;el.setPointerCapture?.(e.pointerId);const move=ev=>{target.x=Math.max(4,Math.min(96,ox+(ev.clientX-sx)/rect.width*100));target.y=Math.max(3,Math.min(97,oy+(ev.clientY-sy)/rect.height*100));updateNfcNode(target)};const up=()=>{window.removeEventListener('pointermove',move);persist()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})};el.onclick=()=>selectNfc(el.dataset.nfc)})}
function nfcInspector(){const el=S.nfc.elements.find(x=>x.id===S.nfcSelected);if(!el)return '';return `<div class="inspector-head"><div><span>CANVA STYLE EDITOR</span><b>${el.type==='image'?'Hình ảnh':el.type==='video'?'Video':el.type==='audio'?'Âm thanh':el.type==='spotify'?'Spotify':el.type==='sticker'?'Sticker':'Văn bản'}</b></div><button id="delete-nfc" type="button">Xoá</button></div>${el.type==='text'?`<label>Nội dung<textarea id="nfc-text">${esc(el.text)}</textarea></label><label>Font<select id="nfc-font"><option ${el.font==='Playfair Display'?'selected':''}>Playfair Display</option><option ${el.font==='Cormorant Garamond'?'selected':''}>Cormorant Garamond</option><option ${el.font==='Georgia'?'selected':''}>Georgia</option><option ${el.font==='DM Sans'?'selected':''}>DM Sans</option><option ${el.font==='Arial'?'selected':''}>Arial</option></select></label>`:''}${el.type==='sticker'?`<label>Nhãn sticker<input id="sticker-text" value="${esc(el.text)}"></label>`:''}${el.type==='spotify'?`<label>Link Spotify<input id="spotify-url" value="${esc(el.url||'')}" placeholder="https://open.spotify.com/track/..."></label><p class="muted">Spotify được nhúng thật vào trang. Người xem cần chạm nút phát theo chính sách của Spotify.</p>`:''}${el.type==='image'?`<label class="upload-box">Thay hình<input id="nfc-replace" type="file" accept="image/*"></label><div class="control"><span>Zoom ảnh</span><input id="nfc-zoom" type="range" min=".5" max="5" step=".05" value="${el.zoom||1}"></div><div class="control"><span>Crop X</span><input id="nfc-cropx" type="range" min="0" max="100" value="${el.cropX??50}"></div><div class="control"><span>Crop Y</span><input id="nfc-cropy" type="range" min="0" max="100" value="${el.cropY??50}"></div>`:''}${el.type==='audio'?`<div class="record-panel"><b>Âm thanh</b><label>Tên hiển thị<input id="audio-label" value="${esc(el.label||el.text||'Lời nhắn thoại')}" placeholder="Lời nhắn thoại"></label><label class="upload-box">Upload audio<input id="audio-upload" type="file" accept="audio/*"></label><button id="record-el" class="btn primary" type="button">${S.recording?'Dừng ghi':'Ghi âm'}</button>${el.src?`<audio controls src="${esc(el.src)}"></audio>`:''}</div>`:''}${el.type==='video'?`<label class="upload-box">Thay video<input id="nfc-replace" type="file" accept="video/*"></label>`:''}<div class="control"><span>Kích thước chữ / icon</span><input id="nfc-size" type="range" min="8" max="60" value="${el.size||16}"></div><div class="control"><span>Độ rộng</span><input id="nfc-width" type="range" min="15" max="98" value="${el.width||84}"></div><div class="control"><span>Chiều cao</span><input id="nfc-height" type="range" min="30" max="600" value="${el.height||(el.type==='spotify'?168:el.type==='audio'?74:el.type==='video'?210:el.type==='image'?220:70)}"></div><div class="grid2"><label>X<input id="nfc-x" type="number" min="0" max="100" value="${Math.round(el.x)}"></label><label>Y<input id="nfc-y" type="number" min="0" max="100" value="${Math.round(el.y)}"></label></div><div class="control"><span>Góc xoay</span><input id="nfc-rotate" type="range" min="-180" max="180" value="${el.rotate||0}"></div><div class="quick-actions"><button id="nfc-center" type="button">↔ Căn giữa</button></div><div class="layer-actions"><button id="nfc-up" type="button">↑ Lên lớp</button><button id="nfc-down" type="button">↓ Xuống lớp</button></div>`}
function wireNfcInspector(){const el=S.nfc.elements.find(x=>x.id===S.nfcSelected);if(!el)return;const on=(id,k,fn=v=>v)=>$(id)?.addEventListener('input',e=>{el[k]=fn(e.target.value);persist();updateNfcNode(el)});on('#nfc-text','text');on('#nfc-font','font');on('#sticker-text','text');on('#audio-label','label');on('#audio-label','text');on('#nfc-zoom','zoom',Number);on('#nfc-cropx','cropX',Number);on('#nfc-cropy','cropY',Number);on('#nfc-size','size',Number);on('#nfc-width','width',Number);on('#nfc-height','height',Number);on('#nfc-x','x',Number);on('#nfc-y','y',Number);on('#nfc-rotate','rotate',Number);on('#spotify-url','url',v=>{const value=String(v||'').trim();if(spotifyEmbedUrl(value)){el.url=value;S.nfc.spotify=value;return value}return el.url||''});$('#delete-nfc')?.addEventListener('click',()=>{S.nfc.elements=S.nfc.elements.filter(x=>x.id!==S.nfcSelected);S.nfcSelected=null;persist();nfcStep()});$('#record-el')?.addEventListener('click',()=>startRecord(S.nfcSelected));$('#audio-upload')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{el.src=await uploadData(await fileToDataURL(f),f.type);persist();nfcStep()}catch(err){alert(err.message)}});$('#nfc-replace')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{el.src=await uploadData(await fileToDataURL(f),f.type);persist();nfcStep()}catch(err){alert(err.message)}});$('#nfc-up')?.addEventListener('click',()=>{swapLayer(S.nfc.elements,S.nfcSelected,1);persist();nfcStep()});$('#nfc-down')?.addEventListener('click',()=>{swapLayer(S.nfc.elements,S.nfcSelected,-1);persist();nfcStep()});$('#nfc-center')?.addEventListener('click',()=>{el.x=50;el.y=50;persist();nfcStep()})}
function bindSpotifyEmbeds(root=document){$$('.spotify-embed iframe',root).forEach(f=>{f.addEventListener('load',()=>{try{f.contentWindow.postMessage({type:'framieReady'},'*')}catch{}})})}

function reviewStep(){$('#setup-body').innerHTML=`<div class="review-grid"><div class="review-card"><div class="review-head"><span>KHUNG VẬT LÝ</span><b>${plans.find(p=>p.code===S.design.plan)?.name}</b></div>${framePreview('review')}<div class="review-meta"><span>${S.design.frame==='portrait'?'Khung đứng':'Khung ngang'}</span><span>${S.design.size}</span></div></div><div class="review-card"><div class="review-head"><span>TRANG NFC</span><b>Preview</b></div><div class="review-phone"><div class="device-phone"><div class="dynamic-island"></div><div class="speaker"></div><div class="device-screen">${nfcPhoneContent()}</div></div></div></div><aside class="review-summary"><span class="eyebrow">TỔNG QUAN</span><h3>${plans.find(p=>p.code===S.design.plan)?.name}</h3><div class="summary-line"><span>Gói</span><b>${money(plans.find(p=>p.code===S.design.plan)?.price)}</b></div><div class="summary-line"><span>Khung</span><b>${S.design.frame==='portrait'?'Khung đứng':'Khung ngang'}</b></div><div class="summary-line"><span>Kích thước</span><b>${S.design.size}</b></div><div class="summary-line"><span>NFC</span><b>${S.nfc.elements.length} lớp nội dung</b></div><div class="security-badge">${S.nfc.passwordEnabled?'🔒 NFC có mật khẩu':'🔓 NFC không đặt mật khẩu'}</div><p>Đây là bản preview cuối. Tất cả nội dung custom, vị trí lớp và thiết lập bảo mật sẽ được lưu cùng thiết kế.</p></aside></div>`;bindAudioTriggers();bindSpotifyEmbeds()}
async function hashText(value){const data=new TextEncoder().encode(String(value));const buf=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function saveDesign(status='draft',toast=false){if(!S.token){location.hash='/login';return null}persist();const nfc=JSON.parse(JSON.stringify(S.nfc));if(nfc.passwordEnabled){nfc.password=String(S.nfc.password||'')}else{delete nfc.password;delete nfc.passwordHash}const body={name:`${plans.find(p=>p.code===S.design.plan)?.name||'Framie'} · ${S.design.size}`,config:S.design,nfc,status};const method=S.loadedDesignId?'PUT':'POST';const endpoint=S.loadedDesignId?`${API}/designs/${S.loadedDesignId}`:API+'/designs';const r=await fetch(endpoint,{method,headers:{'Content-Type':'application/json',Authorization:'Bearer '+S.token},body:JSON.stringify(body)});const d=await r.json();if(!r.ok){alert(d.message||'Không thể lưu');return null}delete S.nfc.password;S.nfc.passwordEnabled=!!d.nfc?.passwordEnabled||!!S.nfc.passwordEnabled;S.loadedDesignId=d.id;persist();if(toast)alert('Đã lưu bản nháp.');return d}
function calcCart(){const sub=S.cart.reduce((a,x)=>a+(x.price*x.qty),0);const discount=S.coupon?Math.round(sub*(S.coupon.discount||0)):0;const shipping=sub>=300000||sub===0?0:30000;return {sub,discount,shipping,total:Math.max(0,sub-discount+shipping)}}
function addCart(plan,qty=1){const p=plans.find(x=>x.code===plan);if(!p)return;const ex=S.cart.find(x=>x.code===plan);if(ex)ex.qty+=qty;else S.cart.push({code:p.code,name:p.name,price:p.price,qty});persist()}
function cart(){if(!S.cart.length){shell(`<main class="page empty-cart"><span class="eyebrow">GIỎ HÀNG</span><h1>Giỏ hàng đang <em>trống.</em></h1><p>Hãy chọn một gói Framie để bắt đầu.</p><a class="btn primary" href="#/shop">Khám phá cửa hàng →</a></main>`);return}const c=calcCart();shell(`<main class="page cart-page"><div class="page-head"><span class="eyebrow">GIỎ HÀNG</span><h1>Những điều bạn đã <em>chọn.</em></h1></div><div class="cart-layout"><section class="cart-list">${S.cart.map((x,i)=>`<article class="cart-row"><div class="cart-thumb ${x.code}"><span>${x.name.replace('Framie ','')}</span></div><div class="cart-detail"><b>${x.name}</b><small>Khung tranh NFC custom</small><div class="cart-controls"><button data-minus="${i}">−</button><span>${x.qty}</span><button data-plus="${i}">+</button><button class="remove" data-remove="${i}">Xóa</button></div></div><strong>${money(x.price*x.qty)}</strong></article>`).join('')}<a class="text-link" href="#/shop">← Tiếp tục mua sắm</a></section><aside class="cart-summary"><span class="eyebrow">TÓM TẮT</span><div class="coupon"><input id="coupon" placeholder="Mã giảm giá"><button id="apply-coupon">Áp dụng</button></div>${S.coupon?`<div class="coupon-note">Đã áp dụng ${esc(S.coupon.code)}</div>`:''}<div class="summary-line"><span>Tạm tính</span><b>${money(c.sub)}</b></div><div class="summary-line"><span>Phí vận chuyển</span><b>${c.shipping?money(c.shipping):'Miễn phí'}</b></div>${c.discount?`<div class="summary-line"><span>Giảm giá</span><b>- ${money(c.discount)}</b></div>`:''}<div class="summary-total"><span>Tổng</span><strong>${money(c.total)}</strong></div><a class="btn primary full" href="#/checkout">Tiến hành thanh toán →</a></aside></div></main>`);$$('[data-minus]').forEach(b=>b.onclick=()=>{const i=+b.dataset.minus;S.cart[i].qty=Math.max(1,S.cart[i].qty-1);persist();cart()});$$('[data-plus]').forEach(b=>b.onclick=()=>{S.cart[+b.dataset.plus].qty++;persist();cart()});$$('[data-remove]').forEach(b=>b.onclick=()=>{S.cart.splice(+b.dataset.remove,1);persist();cart()});$('#apply-coupon').onclick=async()=>{const code=$('#coupon').value.trim();if(!code)return;const r=await fetch(API+'/coupon',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});const x=await r.json();if(!r.ok)return alert(x.message);S.coupon=x;persist();cart()}}
async function checkout(){refreshAuth();if(!S.user){location.hash='/login';return}if(!S.cart.length){if(S.design?.plan){addCart(S.design.plan)}else{location.hash='/shop';return}}const c=calcCart();shell(`<main class="page checkout"><div><span class="eyebrow">CHECKOUT</span><h1>Hoàn tất<br><em>Framie của bạn.</em></h1><form id="co" class="card-form checkout-form"><div class="form-grid"><input name="name" required value="${esc(S.user.name||'')}" placeholder="Tên"><input name="phone" required value="${esc(S.user.phone||'')}" placeholder="Số điện thoại"></div><textarea name="address" required placeholder="Địa chỉ nhận hàng">${esc(S.user.address||'')}</textarea><div class="payment-list"><b>Phương thức thanh toán</b><label><input type="radio" name="payment" value="cod" checked> COD · Thanh toán khi nhận</label><label><input type="radio" name="payment" value="bank"> Chuyển khoản ngân hàng</label></div><button class="btn primary full">Tạo đơn hàng →</button></form></div><aside class="summary"><span class="eyebrow">ĐƠN HÀNG</span>${S.cart.map(x=>`<div class="summary-product"><span>${x.name} × ${x.qty}</span><b>${money(x.price*x.qty)}</b></div>`).join('')}<div class="summary-line"><span>Tạm tính</span><b>${money(c.sub)}</b></div><div class="summary-line"><span>Phí vận chuyển</span><b>${c.shipping?money(c.shipping):'Miễn phí'}</b></div>${c.discount?`<div class="summary-line"><span>Giảm giá</span><b>- ${money(c.discount)}</b></div>`:''}<div class="summary-total"><span>Tổng</span><strong>${money(c.total)}</strong></div></aside></main>`);$('#co').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch(API+'/checkout',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+S.token},body:JSON.stringify({items:S.cart,total:c.total,coupon:S.coupon,planCode:S.design.plan,designId:S.loadedDesignId||null,paymentMethod:f.payment,shipping:f})});const d=await r.json();if(!r.ok)return alert(d.message||'Không thể tạo đơn hàng');S.cart=[];S.coupon=null;persist();shell(`<main class="success-page"><div class="success-card"><div class="success-icon">✓</div><span class="eyebrow">ĐƠN HÀNG ĐÃ TẠO</span><h1>Cảm ơn quý khách đã tin tưởng và sử dụng dịch vụ của <em>framie</em>!</h1><p>Đơn hàng ${d.orderCode} đã được tạo thành công. Cảm ơn quý khách hàng đã tin tưởng và sử dụng dịch vụ của <b>framie</b>!</p><button id="success-ok" class="btn primary">OK · Về Dashboard</button></div></main>`);$('#success-ok').onclick=()=>location.hash='/dashboard'}}
function openDashboardPreview(d){const m=document.createElement('div');m.className='modal';const protectedNote=d.nfc?.passwordEnabled?'<div class="security-badge">🔒 Trang NFC có mật khẩu bảo vệ</div>':'';m.innerHTML=`<div class="modal-card dashboard-preview-modal"><button class="close">×</button><div class="modal-head"><div><span class="eyebrow">XEM LẠI NFC</span><h2>${esc(d.name)}</h2>${protectedNote}</div></div><div class="dashboard-preview-phone"><div class="device-phone"><div class="dynamic-island"></div><div class="speaker"></div><div class="device-screen">${nfcPhoneContentFrom(d.nfc||defaultNfc())}</div></div></div></div>`;document.body.appendChild(m);$('.close',m).onclick=()=>m.remove();bindAudioTriggers(m);bindSpotifyEmbeds(m)}
async function dashboard(){
  refreshAuth();if(!S.user){location.hash='/login';return}
  const h={Authorization:'Bearer '+S.token};
  const [ds,os,an]=await Promise.all([fetch(API+'/designs',{headers:h}).then(r=>r.json()),fetch(API+'/orders',{headers:h}).then(r=>r.json()),fetch(API+'/analytics',{headers:h}).then(r=>r.json())]);
  shell(`<main class="page dashboard"><div class="dash-head"><div><span class="eyebrow">DASHBOARD</span><h1>Xin chào, ${esc(S.user.name)}.</h1><p>Quản lý thiết kế, NFC và đơn hàng của bạn.</p></div><a href="#/setup" class="btn primary">Tạo Framie mới →</a></div><div class="dash-tabs"><button class="active" data-dtab="overview">Tổng quan</button><button data-dtab="orders">Đơn hàng</button><button data-dtab="nfc">NFC</button><button data-dtab="account">Tài khoản</button></div><div id="dash-content"></div></main>`);
  const render=tab=>{const el=$('#dash-content');
    if(tab==='overview')el.innerHTML=`<div class="stats"><div><b>${ds.length}</b><span>Thiết kế</span></div><div><b>${os.length}</b><span>Đơn hàng</span></div><div><b>${an.totalScans||0}</b><span>Lượt quét NFC</span></div></div><section class="dash-section"><div class="section-head-row"><h2>Thiết kế gần đây</h2><a class="text-link" href="#/setup">+ Tạo mới</a></div>${ds.length?ds.map(d=>`<div class="dash-row"><div class="dash-thumb ${d.config?.color||'cream'}"></div><div><b>${esc(d.name)}</b><small>${new Date(d.updatedAt).toLocaleDateString('vi-VN')} · ${esc(d.status)}</small></div><button class="text-link dash-preview" data-preview-id="${d.id}" type="button">Xem lại NFC →</button><a class="text-link" href="#/setup?design=${d.id}">Chỉnh sửa →</a></div>`).join(''):'<div class="empty">Chưa có bản thiết kế.</div>'}</section>`;
    if(tab==='orders')el.innerHTML=`<section class="dash-section"><h2>Đơn hàng của tôi</h2>${os.length?os.map(o=>`<div class="dash-row order-row"><div class="order-no">${o.code?.slice(-3)||o.id}</div><div><b>${o.code||'Order #'+o.id}</b><small>${new Date(o.createdAt).toLocaleDateString('vi-VN')} · ${money(o.total)}</small></div><span class="status">${o.orderStatus==='pending'?'Chờ duyệt':o.orderStatus==='shipping'?'Đang giao':'Đã giao'}</span></div>`).join(''):'<div class="empty">Chưa có đơn hàng.</div>'}</section>`;
    if(tab==='nfc')el.innerHTML=`<section class="dash-section"><div class="section-head-row"><div><h2>Quản lý landing page</h2><p class="muted">Mỗi NFC liên kết với một URL và một thiết lập mật khẩu riêng.</p></div><span class="rating">${an.totalScans||0} lượt</span></div>${an.byDesign?.length?an.byDesign.map(x=>{const d=ds.find(z=>z.id===x.id),url=`${location.origin}/#/m/${x.id}`;return `<article class="nfc-management-card"><div class="nfc-management-head"><div><b>${esc(x.name)}</b><small>NFC #${x.id} · ${x.scans} lượt quét</small></div><span class="security-badge">${d?.nfc?.passwordEnabled?'🔒 Có mật khẩu':'🔓 Không mật khẩu'}</span></div><div class="nfc-url-row"><span>URL</span><code>${esc(url)}</code><button class="text-link copy-nfc-url" data-url="${esc(url)}" type="button">Sao chép</button></div><div class="nfc-credential-row"><span>Mật khẩu</span><strong>${d?.nfc?.passwordEnabled?'••••••••':'Không đặt'}</strong>${d?.nfc?.passwordEnabled?`<button class="text-link view-nfc-password" data-password-id="${x.id}" type="button">Xem</button><button class="text-link dash-password" data-password-id="${x.id}" data-password-enabled="1" type="button">Đổi mật khẩu</button>`:`<button class="text-link dash-password" data-password-id="${x.id}" data-password-enabled="0" type="button">Đặt mật khẩu</button>`}<a class="text-link" href="#/m/${x.id}" target="_blank">Mở landing →</a></div></article>`}).join(''):'<div class="empty">Chưa có landing page nào.</div>'}</section>`;
    if(tab==='account')el.innerHTML=`<div class="account-grid"><form id="profile-form" class="card-form"><span class="eyebrow">THÔNG TIN TÀI KHOẢN</span><h3>Cập nhật hồ sơ</h3><input name="name" value="${esc(S.user.name||'')}" placeholder="Họ tên"><input name="phone" value="${esc(S.user.phone||'')}" placeholder="Số điện thoại"><textarea name="address" placeholder="Địa chỉ giao hàng mặc định">${esc(S.user.address||'')}</textarea><button class="btn primary">Lưu thay đổi</button></form><form id="password-form" class="card-form"><span class="eyebrow">BẢO MẬT</span><h3>Đổi mật khẩu</h3><input type="password" name="current" placeholder="Mật khẩu hiện tại"><input type="password" name="next" minlength="6" placeholder="Mật khẩu mới"><button class="btn ghost">Đổi mật khẩu</button></form><div class="card-form"><span class="eyebrow">PHIÊN ĐĂNG NHẬP</span><h3>Google / Email</h3><p class="muted">Bạn đang đăng nhập với ${esc(S.user.email)}.</p><button id="logout" class="btn ghost" type="button">Đăng xuất</button></div></div>`;
    if(tab==='overview'){$$('.dash-preview').forEach(b=>b.onclick=()=>{const d=ds.find(x=>String(x.id)===b.dataset.previewId);if(d)openDashboardPreview(d)})}
    if(tab==='nfc'){
      $$('.copy-nfc-url').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.url);b.textContent='Đã sao chép';setTimeout(()=>b.textContent='Sao chép',1200)}catch{prompt('URL landing page',b.dataset.url)}});
      $$('.view-nfc-password').forEach(b=>b.onclick=()=>viewNfcPassword(Number(b.dataset.passwordId)));
      $$('.dash-password').forEach(btn=>btn.onclick=async()=>{const id=Number(btn.dataset.passwordId);const enabled=btn.dataset.passwordEnabled==='1';const password=enabled?prompt('Nhập mật khẩu NFC mới (tối thiểu 4 ký tự). Để trống để tắt:'):prompt('Đặt mật khẩu NFC (tối thiểu 4 ký tự):');if(password===null)return;if(enabled&&!password){const r=await fetch(`${API}/designs/${id}/nfc-password`,{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+S.token},body:JSON.stringify({enabled:false})});if(r.ok){alert('Đã tắt mật khẩu NFC.');dashboard()}return}if(String(password||'').length<4){alert('Mật khẩu NFC tối thiểu 4 ký tự.');return}const r=await fetch(`${API}/designs/${id}/nfc-password`,{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+S.token},body:JSON.stringify({enabled:true,password})});const x=await r.json();if(!r.ok)return alert(x.message||'Không thể cập nhật mật khẩu.');alert('Đã cập nhật mật khẩu NFC.');dashboard()});
    }
    if(tab==='account'){$('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const r=await fetch(API+'/auth/profile',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+S.token},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});const x=await r.json();if(!r.ok)return alert(x.message);S.user=x.user;localStorage.setItem('framie_user',JSON.stringify(S.user));persist();alert('Đã cập nhật thông tin.')});$('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const r=await fetch(API+'/auth/password',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+S.token},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});const x=await r.json();if(!r.ok)return alert(x.message);alert('Đã đổi mật khẩu.');e.currentTarget.reset()});$('#logout')?.addEventListener('click',signout)}
  };
  $$('[data-dtab]').forEach(b=>b.onclick=()=>{$$('[data-dtab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.dtab)});render('overview')
}
async function viewNfcPassword(id){const r=await fetch(`${API}/designs/${id}/nfc-password`,{headers:{Authorization:'Bearer '+S.token}});const d=await r.json();if(!r.ok)return alert(d.message||'Không thể đọc mật khẩu.');const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card password-modal"><button class="close" type="button">×</button><span class="eyebrow">NFC PASSWORD</span><h2>Mật khẩu landing page</h2><div class="password-reveal"><input id="reveal-password" type="password" value="${esc(d.password||'')}" readonly><button id="toggle-reveal" type="button">Hiện</button></div><p class="muted">Mật khẩu được hiển thị chỉ cho chủ thiết kế đã đăng nhập.</p></div>`;document.body.appendChild(m);$('.close',m).onclick=()=>m.remove();$('#toggle-reveal',m).onclick=()=>{const i=$('#reveal-password');const show=i.type==='password';i.type=show?'text':'password';$('#toggle-reveal').textContent=show?'Ẩn':'Hiện'} }
async function renderPublicUnlocked(d){fetch(API+'/nfc/'+d.id+'/scan',{method:'POST'}).catch(()=>{});document.title=`${d.name} · framie`;shell(`<main class="public-page real-memory-page"><section class="public-memory-hero"><div><span class="eyebrow">FRAMIE MEMORY · ${d.nfc?.passwordEnabled?'PRIVATE':'PERSONAL'}</span><h1>Một điều nhỏ,<br><em>được giữ lại.</em></h1><p>Một không gian kỷ niệm được tạo riêng cho bạn. Cuộn xuống để xem toàn bộ nội dung đã được gửi gắm.</p></div><div class="memory-meta"><span>FRAMIE</span><b>#${d.id}</b></div></section><section class="memory-content"><div class="memory-stage-shell"><div class="nfc-web-canvas-wrap">${nfcLandingContentFrom(d.nfc||defaultNfc())}</div></div></section><section class="memory-footer"><span>FRAMIE · MADE FOR TWO</span><p>Một cú chạm. Một câu chuyện. Một nơi để nhớ.</p></section></main>`);bindAudioTriggers();bindSpotifyEmbeds()}
async function nfcPublic(id){const r=await fetch(API+'/nfc/'+id);const d=await r.json();if(!r.ok)return shell(`<main class="page narrow"><span class="eyebrow">NFC</span><h1>Trang ký ức không tồn tại.</h1><p>${esc(d.message||'Không tìm thấy Framie.')}</p></main>`);if(d.protected){shell(`<main class="nfc-lock-page"><div class="nfc-lock-card"><div class="lock-icon">🔒</div><span class="eyebrow">FRAMIE PRIVATE MEMORY</span><h1>Đây là một câu chuyện <em>riêng tư.</em></h1><p>Nhập mật khẩu do người tạo Framie cung cấp để mở nội dung kỷ niệm.</p><form id="nfc-unlock-form"><input id="nfc-unlock-password" type="password" placeholder="Mật khẩu" autocomplete="current-password" required><button class="btn primary full">Mở nội dung →</button></form><small id="nfc-unlock-error"></small></div></main>`);$('#nfc-unlock-form').onsubmit=async e=>{e.preventDefault();const password=$('#nfc-unlock-password').value;const rr=await fetch(`${API}/nfc/${id}/unlock`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const data=await rr.json();if(!rr.ok){$('#nfc-unlock-error').textContent=data.message||'Mật khẩu không đúng.';return}renderPublicUnlocked(data)};return}return renderPublicUnlocked(d)}
function framePreviewFromConfig(config){const c=config||{};return `<div class="public-frame-card"><span class="eyebrow">FRAMIE · BẢN THIẾT KẾ</span><div class="frame-preview ${c.frame||'portrait'} ${c.color||'cream'} public-frame">${(c.elements||[]).slice().sort((a,b)=>(a.z||0)-(b.z||0)).map(e=>renderPhysical(e,false)).join('')}<span class="nfc-badge">NFC</span></div><div class="public-frame-meta"><span>${c.frame==='landscape'?'Khung ngang':'Khung đứng'}</span><span>${c.size||''}</span></div></div>`}

function parseRoute(){const raw=location.hash.slice(1)||'/';const [p,q='']=raw.split('?');return {p,q:new URLSearchParams(q)}}
async function setup(){refreshAuth();if(!S.user){location.hash='/login';return}const {q}=parseRoute();const id=Number(q.get('design'));if(id&&(!S.loadedDesignId||S.loadedDesignId!==id)){try{const r=await fetch(API+'/designs/'+id,{headers:{Authorization:'Bearer '+S.token}});if(r.ok){const d=await r.json();S.design=d.config||defaultDesign();S.nfc=d.nfc||defaultNfc();S.loadedDesignId=id;S.step=4;persist()}}catch{} } renderSetup()}
function route(){const {p}=parseRoute();if(p==='/')home();else if(p==='/about')about();else if(p==='/blog')blog();else if(p.startsWith('/blog/'))blogPost(p.slice(6));else if(p==='/shop')shop();else if(p==='/contact')contact();else if(p==='/policy')policy();else if(p==='/login'||p==='/register'||p==='/forgot')auth();else if(p==='/setup')setup();else if(p==='/dashboard')dashboard();else if(p==='/cart')cart();else if(p==='/checkout')checkout();else if(p.startsWith('/m/'))nfcPublic(p.slice(3));else home()}
window.addEventListener('hashchange',route);route();
